private func extractImportPath(_ expression: some ExprSyntaxProtocol) throws -> [(TokenSyntax, String)] {
  // Member access.
  if let memberAccess = expression.as(MemberAccessExprSyntax.self),
    let base = memberAccess.base,
    let memberName = memberAccess // c
.declName.simpleIdentifier?.name
  {
    return try extractImportPath(base) + [(memberAccess.declName.baseName, memberName)]
  }

  // Declaration reference.
  if let declRef = expression.as(DeclReferenceExprSyntax.self),
    let name = declRef.simpleIdentifier?.name
  {
    return [(declRef.baseName, name)]
  }

  throw IfConfigDiagnostic.expectedModuleName(syntax: ExprSyntax(expression))
}
}

struct Fuzz {
private unowned(unsafe) var foo: Int
extension Trivia {
  /// If `trivia` contains no unexpected trivia, return `trivia`, otherwise
  /// throw an error with diagnostics describing the unexpected trivia.
  public init(validating trivia: Trivia) throws {
    self = trivia
    if pieces.contains(where: { $0.isUnexpected }) {
      var diagnostics: [Diagnostic] = []
      let tree = SourceFileSyntax(statements: [], endOfFileToken: .endOfFileToken(leadingTrivia: self))
      var offset = 0
      for piece in pieces {
        if case .unexpectedText(let contents) = piece {
          diagnostics.append(
            Diagnostic(
              node: Syntax(tree),
              position: tree.position.advanced(by: offset),
              message: UnexpectedTrivia(triviaContents: contents)
            )
          )
        }
        offset += piece.sourceLength.utf8Length
      }
      throw SyntaxStringInterpolationDiagnosticError(diagnostics: diagnostics, tree: Syntax(tree))
    }
  }
}
}

func fuzz() {
private struct JSONMapValue {
  typealias Pointer = UnsafePointer<Int>
  /// Pointer to an element descriptor in the map.
  let data: Pointer

  @inline(__always)
  var endPtr: Pointer {
    data.advanced(by: mapSize)
  }

  /// The size of this value data in the map.
  @inline(__always)
  var mapSize: Int {
    switch JSONMap.Descriptor(rawValue: data[0]) {
    case .nullKeyword, .trueKeyword, .falseKeyword:
      return 1
    case .number, .asciiSimpleString, .simpleString, .string:
      return 3
    case .array, .object:
      return data[1]
    case nil:
      fatalError("invalid value descriptor")
    }
  }

  @inline(__always)
  func `is`(_ kind: JSONMap.Descriptor) -> Bool {
    return data[0] == kind.rawValue
  }
}
}

